// Settings defines model for Settings.
type Settings struct {
	// Admin Admin API + web UI listener. Always HTTPS; a self-signed certificate is
	// generated on first run. Bind it to a management address so machines on
	// the deployment network cannot reach the admin API.
	Admin struct {
		// BindAddress IP to listen on; `0.0.0.0` for all (not recommended).
		BindAddress string `json:"bindAddress"`

		// CertificatePem Null keeps the generated certificate.
		CertificatePem *string `json:"certificatePem"`
		Port           int     `json:"port"`
		PrivateKeyPem  *string `json:"privateKeyPem"`
	} `json:"admin"`

	// Architectures Which client architectures are answered at all.
	Architectures *struct {
		// Bios Windows 11 requires UEFI.
		Bios *bool `json:"bios,omitempty"`

		// HttpBoot Answer UEFI HTTP Boot (HTTPClient) requests.
		HttpBoot  *bool `json:"httpBoot,omitempty"`
		UefiArm64 *bool `json:"uefiArm64,omitempty"`
		UefiX64   *bool `json:"uefiX64,omitempty"`
	} `json:"architectures,omitempty"`

	// BootPrompt What a network-booted machine shows when no deployment is armed for it
	// (ADR 0013). Every client that passes the architecture and interface MAC
	// filters boots WinPE; DHCP does not answer a client until it has a
	// profile to offer (its own, or `defaultProfileId`).
	BootPrompt *struct {
		// ArmedCountdownSeconds Countdown before an armed deployment starts; any key opens the menu instead.
		ArmedCountdownSeconds *int `json:"armedCountdownSeconds,omitempty"`

		// DefaultProfileId Preselected in the menu for clients without a profile, and the boot
		// image source for them. Null: such clients are not answered.
		DefaultProfileId *string `json:"defaultProfileId"`
		HasPassword      *bool   `json:"hasPassword,omitempty"`

		// Password Stored as an argon2id hash; never returned. Omit or null to keep the current password.
		Password *string `json:"password"`

		// RequirePassword **Debug only.** False shows the profile menu without a password: anyone
		// at a machine on a deployment network can re-image it. Raises the
		// `boot_prompt_password_disabled` health warning, a UI banner, a startup
		// log warning, and a banner on the WinPE screen.
		RequirePassword *bool `json:"requirePassword,omitempty"`

		// TimeoutSeconds Prompt countdown; at zero the agent sets UEFI BootNext to the local disk and reboots.
		TimeoutSeconds *int `json:"timeoutSeconds,omitempty"`
	} `json:"bootPrompt,omitempty"`

	// ContentHttps TLS for the content listener on interfaces with `services.https` enabled (Phase 6; stored but unused until then).
	ContentHttps *struct {
		// CertificatePem Null generates a certificate from an internal CA (download via `/settings/content-ca`).
		CertificatePem *string `json:"certificatePem"`
		PrivateKeyPem  *string `json:"privateKeyPem"`
	} `json:"contentHttps,omitempty"`
	Etag *string `json:"etag,omitempty"`

	// Interfaces Deployment-network interfaces. Each runs its own DHCP mode and content services.
	Interfaces []InterfaceSettings `json:"interfaces"`

	// Storage Content store (ADR 0015). Its location is the `-content` startup flag
	// (default `<data>/content`), not a setting.
	Storage *struct {
		// ReserveBytes Free space the content store never uses (default 5 GiB). Uploads and
		// imports that wouldn't leave this much free are refused with `507`;
		// running jobs fail before going below it.
		ReserveBytes *int64 `json:"reserveBytes,omitempty"`
	} `json:"storage,omitempty"`

	// Tftp Server-side TFTP limits, applied to every client (firmware PXE, Boot
	// Manager). Negotiated options are capped to these, which protects clients
	// from a BCD that asks for more than the network can carry. Defaults are
	// provisional until the physical I210 runs (Phase 1 tasks 7–8); see the
	// Phase 1 findings, "Chosen defaults".
	Tftp *struct {
		// MaxBlockSize 16384 with a window of 16 lost IP fragments and failed to boot on Hyper-V; 8192/8 never lost a packet.
		MaxBlockSize *int `json:"maxBlockSize,omitempty"`

		// MaxWindowSize Blocks sent before waiting for an ACK.
		MaxWindowSize *int `json:"maxWindowSize,omitempty"`

		// TimeoutSeconds Retransmit timeout when the client doesn't negotiate `timeout`. Boot
		// Manager never ACKs early to request a resend, so each lost block costs a
		// full timeout; a transfer is abandoned after 5 consecutive timeouts.
		TimeoutSeconds *int `json:"timeoutSeconds,omitempty"`
	} `json:"tftp,omitempty"`
}

